using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.GroupAlgebra;

internal sealed class ProjectiveConjugationTraceDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Projectivity over a finite group algebra is coefficient projectivity together with conjugation trace one in the full endomorphism ring.",
        H("Projective Modules and Conjugation Trace One"),
        Blocks(
            Paragraph(Text("Let R be an arbitrary commutative ring, G a finite group, V an arbitrary R-module and rho an actual Representation R G V. The coefficient ring, group and module have independent universes. The ring and module may be zero and the group may be trivial or nonabelian. There is no characteristic, p-group, nilpotence, group-order-unit, finite-generation, finite-presentation or finite-dimensionality assumption. End_R(V) is used with its actual generally noncommutative composition.")),
            Paragraph(Text("This reconstructs the classical projectivity/trace-one criterion. The supplied attribution is Aljadeff--Ginosar (1996), Lemma 4, and Aljadeff--Kassel, https://arxiv.org/abs/math/0012038. No literature novelty or independent bibliographic verification is claimed. The proof uses the repository orbit-cover section and Mathlib's unnormalised conjugation sum.")),
            Describe.Lean(
                DescribeId.Create("projective-iff-projective-and-conjugation-trace-one"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/ProjectiveConjugationTrace.projective_iff_projective_and_conjugation_trace_one"),
                H("The full arbitrary-coefficient criterion"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Exact public telescope: universe uR uG uV; {R : Type uR} {G : Type uG} {V : Type uV} [CommRing R] [Group G] [Fintype G] [AddCommGroup V] [Module R V] (rho : Representation R G V). The conclusion is Module.Projective R[G] rho.asModule iff Module.Projective R V and there exists t : Module.End R V with (sum g : G, (rho g).comp (t.comp (rho g inverse))) = LinearMap.id. All three universes are independent. The sum is a finite sum of actual R-linear endomorphisms, and no multiplication of those endomorphisms is commuted.")),
                    Paragraph(Text("For necessity, reuse coefficient_projective_of_projective at its original PGroupProjectiveNormRing source location. It realizes rho.asModule as a retract of its actual free R[G]-module, uses MonoidAlgebra.basis G R to make that free cover R-free, restricts the split maps along the actual compatible scalar towers, and transports R-projectivity through rho.asModuleEquiv. This helper has no group finiteness or p-nilpotence premise. Its proof is not copied into this module.")),
                    Paragraph(Text("The shared orbit_section_of_projective is factored at the same original source location and is consumed both here and by the old norm_section_of_projective. Its rightTranslate action is T_g(f)(h)=f(h*g), and its actual orbit-cover is q(f)=sum_g rho(g)f(g inverse). The delta function at 1 proves q surjective. Convert q to an R[G]-linear map with Representation.IntertwiningMap.equivLinearMapAsModule, lift the identity by Module.projective_lifting_property, and convert the resulting section back to an intertwining map S from rho to rightTranslate. The resulting split equation q(S(v))=v holds for every v, not only invariant vectors.")),
                    Paragraph(Text("Define t(v)=S(v)(1). The intertwining equation evaluated at 1 gives t(rho(g)v)=S(v)(g), retaining the order h*g in the right action. Reindex q(S(v)) by inversion to obtain sum_g rho(g inverse)t(rho(g)v)=v. A second inversion bijection identifies the corresponding sum of endomorphisms with sum_g rho(g)t(rho(g inverse)(-)), the displayed convention. The private sum_inverse_conjugates helper implements this finite bijection and is consumed in both directions of the criterion.")),
                    Paragraph(Text("For sufficiency, Module.Projective.of_lifting_property'' reduces the goal to splitting an arbitrary surjective R[G]-linear map f from the actual free cover X=(rho.asModule to finitely supported R[G]) onto rho.asModule. Use the natural R-module structure on X, the actual R/R[G] scalar towers and LinearMap.CompatibleSMul to restrict f to R. Base-ring projectivity of V lifts rho.asModuleEquiv.symm through this restricted map to an R-linear s : V to X, with f(s(v))=rho.asModuleEquiv.symm(v). Thus base-ring projectivity supplies a genuine linear section rather than a set-theoretic choice or a freeness assumption on V.")),
                    Paragraph(Text("Set pi=s composed with t composed with rho.asModuleEquiv. The actual LinearMap.sumOfConjugatesEquivariant G pi is an R[G]-linear map from rho.asModule to X. This Mathlib construction works over CommRing and takes the unnormalised sum of inverse conjugates; equivariantProjection, which divides by the group order, is not used. Apply f term by term using R[G]-linearity and the section equation for s. Under rho.asModuleEquiv, a basis scalar single(g,1) acts as rho(g), so the composite becomes the inverse-conjugation trace of t. The same inversion bijection and the supplied trace-one equation make the composite the identity. This actual splitting establishes group-algebra projectivity.")),
                    Paragraph(Text("The two conditions on the right cannot be merged by dropping base-ring projectivity. For a trivial group, t=id already has conjugation trace id on every module, while projectivity over R[G]=R remains precisely R-projectivity. This explains why a norm-one endomorphism alone supplies only the relative splitting condition. The theorem is a prerequisite for later cyclic p-group detection; it does not prove that detection theorem, construct a conjugation ring automorphism, lift a ring norm-one element, or identify subgroup sums for a chosen generator."))),
                DescribeRole.Theorem))));
}
